<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$result=mysqli_query($koneksi,"SELECT p.*,r.kode_role,r.nama_role,ps.nama_program_studi,f.nama_fakultas FROM pengguna p JOIN roles r ON p.id_role=r.id_role LEFT JOIN program_studi ps ON p.id_program_studi=ps.id_program_studi LEFT JOIN fakultas f ON p.id_fakultas=f.id_fakultas ORDER BY p.id_pengguna DESC");?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pengguna</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading page-heading-flex"><div><span class="eyebrow">MANAJEMEN PENGGUNA</span><h1>Pengguna</h1><p>Kelola akun dan role pengguna aplikasi.</p></div><a class="btn btn-primary" href="pengguna_tambah.php">+ Tambah Pengguna</a></div><?php flash_html();?><div class="dashboard-panel"><div class="table-responsive"><table class="data-table"><thead><tr><th>No</th><th>Username</th><th>Nama</th><th>Role</th><th>Unit</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $no=1;while($r=mysqli_fetch_assoc($result)):?><tr><td><?=$no++?></td><td><strong><?=e($r['username'])?></strong></td><td><?=e($r['nama_lengkap'])?></td><td><span class="badge"><?=e($r['kode_role'])?></span></td><td><?=e($r['nama_program_studi']?:($r['nama_fakultas']?:'-'))?></td><td><?=e($r['status_aktif'])?></td><td><div class="action-group"><a class="btn btn-sm btn-outline" href="pengguna_edit.php?id=<?=$r['id_pengguna']?>">Edit</a><form method="post" action="pengguna_hapus.php" onsubmit="return confirm('Hapus pengguna ini?');"><input type="hidden" name="id" value="<?=$r['id_pengguna']?>"><?=csrf_field()?><button class="btn btn-sm btn-danger">Hapus</button></form></div></td></tr><?php endwhile;?></tbody></table></div></div></main><script src="script.js"></script></body></htm